console.log("BM25 SCORING: What");
function bm25(tf, df, N, dl, avgdl){ var k1=1.2, b=0.75; var idf=Math.log(1+(N-df+0.5)/(df+0.5)); return idf*((tf*(k1+1))/(tf+k1*(1-b+b*dl/avgdl))); }
console.log("term tf=3, df=10, N=1000, dl=200, avgdl=250 -> score "+bm25(3,10,1000,200,250).toFixed(3));
console.log("term tf=1, df=500 -> score "+bm25(1,500,1000,200,250).toFixed(3));
console.log("Rare terms score higher; length normalization penalizes long docs.");

